<script setup>import {ref,onMounted,onUnmounted} from 'vue';import {watchNotifications} from '../services/data';const props=defineProps(['user']);const items=ref([]);let stop;onMounted(()=>stop=watchNotifications(props.user.uid,v=>items.value=v));onUnmounted(()=>stop?.());</script><template><h1>Gelen Gidenler</h1><div class="grid"><div class="card"><h2>📥 Gelen mesajlar</h2><p class="muted">Sana gönderilen mesajlar ve klan davetleri.</p></div><div class="card"><h2>📤 Gidenler</h2><p class="muted">Gönderdiğin iletişim geçmişi.</p></div><div class="card"><h2>🏷 Etiketlemeler</h2><p class="muted">@kullanıcıadı etiketleri yalnızca uygulama içinde popup/toast olarak gösterilir.</p></div><div class="card"><h2>🔔 Bildirim geçmişi</h2><div class="list"><div v-for="n in items" :key="n.id" class="list-item"><b>{{n.title||'Bildirim'}}</b><p>{{n.body||n.message}}</p></div><div v-if="!items.length" class="muted">Henüz bildirim yok.</div></div></div></div></template>